command:
/**
 * Astrogation Jump Check & Mishap Resolver
 * Calculates course plot, rolls 1d20 + INT, and draws mishaps automatically if failed.
 */
const speaker = ChatMessage.getSpeaker();
const actor = game.actors.get(speaker.actor) || canvas.tokens.controlled[0]?.actor;

const intMod = actor ? (actor.system?.abilities?.int?.mod ?? 0) : 0;
const actorName = actor ? actor.name : "Navigator";

new Dialog({
  title: "Astrogation Course Plot",
  content: `
    <form class="darkspace-dialog">
      <div class="form-group" style="margin-bottom: 10px;">
        <label><b>Navigator:</b> ${actorName} (INT Mod: ${intMod >= 0 ? '+' : ''}${intMod})</label>
      </div>
      <div class="form-group" style="margin-bottom: 10px;">
        <label><b>Hyperspace Vector / Target:</b></label>
        <select id="jump-dc" style="width: 100%;">
          <option value="9">Standard In-System / Charted Lane (DC 9 - Easy)</option>
          <option value="12" selected>Interstellar Jump / Normal Route (DC 12 - Normal)</option>
          <option value="15">Hazardous / Asteroid-Dense Sector (DC 15 - Hard)</option>
          <option value="18">Uncharted Deep Void / Black Hole Fringe (DC 18 - Extreme)</option>
        </select>
      </div>
    </form>
  `,
  buttons: {
    roll: {
      icon: '<i class="fas fa-compass"></i>',
      label: "Engage FTL Drive",
      callback: async (html) => {
        const dc = parseInt(html.find("#jump-dc").val());
        const roll = await new Roll(`1d20 + ${intMod}`).evaluate();
        const success = roll.total >= dc;
        const rollHtml = await roll.render();

        let outcomeHtml = "";
        if (success) {
          const daysRoll = await new Roll("1d6").evaluate();
          outcomeHtml = `
            <div style="background: rgba(0, 150, 0, 0.15); border: 1px solid #4CAF50; padding: 8px; border-radius: 4px; margin-top: 8px;">
              <b style="color: #4CAF50;"><i class="fas fa-check-circle"></i> Jump Vector Confirmed!</b>
              <p style="margin: 4px 0 0 0;">Course plot successful (DC ${dc}). Transit time: <b>${daysRoll.total} days</b> in hyperspace.</p>
            </div>
          `;
        } else {
          outcomeHtml = `
            <div style="background: rgba(200, 0, 0, 0.15); border: 1px solid #F44336; padding: 8px; border-radius: 4px; margin-top: 8px;">
              <b style="color: #F44336;"><i class="fas fa-exclamation-triangle"></i> Astrogation Mishap!</b>
              <p style="margin: 4px 0 0 0;">Jump calculations failed (DC ${dc}). Dropping out of FTL into emergency anomaly...</p>
            </div>
          `;
        }

        await ChatMessage.create({
          user: game.user._id,
          speaker: ChatMessage.getSpeaker({ actor }),
          flavor: `<b>Astrogation Course Plot</b> &mdash; Target DC ${dc}`,
          content: `${rollHtml}${outcomeHtml}`
        });

        if (!success) {
          const pack = game.packs.get("darkspace.rollable-tables");
          if (pack) {
            const table = await pack.getDocument("dsTabAstroMishap");
            if (table) {
              await table.draw({ displayChat: true });
            }
          }
        }
      }
    },
    cancel: {
      icon: '<i class="fas fa-times"></i>',
      label: "Cancel"
    }
  },
  default: "roll"
}).render(true);
